  function applyAt(){
    const host=document.querySelector("#page-all:not([hidden]),#page-menu:not([hidden])")||document;
    const q=atState.q.trim().toLowerCase();let shown=0;
    host.querySelectorAll(".at-group").forEach(g=>{
      let vis=0;g.querySelectorAll(".trow").forEach(r=>{const ok=!q||r.dataset.name.includes(q);r.hidden=!ok;if(ok)vis++});
      g.querySelectorAll(".at-sub").forEach(sb=>sb.hidden=![...sb.querySelectorAll(".trow")].some(r=>!r.hidden));
      const on=vis>0;g.hidden=!on;if(on)shown+=vis});
    host.querySelectorAll("[data-atcat]").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.atcat===atState.cat)));
    const e=host.querySelector("#atEmpty");if(e)e.hidden=shown>0;
  }
  function atJump(id){
    const host=document.querySelector("#page-all:not([hidden]),#page-menu:not([hidden])");if(!host)return;
    atState.cat=id;atMark(id);atLock=performance.now()+900;
    const bar=host.querySelector(".at-bar"),off=(bar?bar.getBoundingClientRect().height:0)+86;
    const t=id==="all"?host.querySelector("#atList"):host.querySelector(`.at-group[data-cat="${id}"]`);if(!t)return;
    window.scrollTo({top:t.getBoundingClientRect().top+scrollY-off+(id==="all"?0:8),behavior:RM0?"auto":"smooth"});
  }
  let atLock=0;
  function atMark(id){const host=document.querySelector("#page-all:not([hidden]),#page-menu:not([hidden])");if(!host)return;
    host.querySelectorAll("[data-atcat]").forEach(b=>{const on=b.dataset.atcat===id;b.setAttribute("aria-pressed",String(on));if(on&&b.scrollIntoView&&b.parentElement.scrollWidth>b.parentElement.clientWidth){const p=b.parentElement;p.scrollTo({left:b.offsetLeft-p.clientWidth/2+b.offsetWidth/2,behavior:"smooth"})}})}
  window.addEventListener("scroll",()=>{if(performance.now()<atLock)return;const host=document.querySelector("#page-all:not([hidden]),#page-menu:not([hidden])");if(!host)return;
    const bar=host.querySelector(".at-bar");if(!bar)return;const y=bar.getBoundingClientRect().bottom+40;let cur="all";
    host.querySelectorAll(".at-group:not([hidden])").forEach(g=>{const r=g.getBoundingClientRect();if(r.top<=y&&r.bottom>y)cur=g.dataset.cat});
    const list=host.querySelector("#atList");if(list&&list.getBoundingClientRect().top>y)cur="all";
    if(cur!==atState.cat){atState.cat=cur;atMark(cur)}},{passive:true});
